#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int vi_pham = 0;
    for (int i = 0; i < n; i++) {
        int vai_tro, hanh_dong;
        scanf("%d %d", &vai_tro, &hanh_dong);
        if (vai_tro == 1 && hanh_dong == 2) vi_pham++;
    }
    printf("%d\n", vi_pham);
    return 0;
}
